// Bundles the repository's knowledge documents (AGENTS.md and docs/**/*.md) into
// src/content/knowledge.generated.ts so the admin can show the *deployed* revision on the edge runtime,
// where there is no file system. Each file carries its git blob sha, the same id GitHub reports, so an edit
// can be checked against the repository's current revision. The generated file is not committed.
import { execSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

function walk(dir) {
  return readdirSync(dir).flatMap((name) => {
    const full = join(dir, name);
    return statSync(full).isDirectory() ? walk(full) : full.endsWith(".md") ? [full] : [];
  });
}

const blobSha = (text) => {
  const body = Buffer.from(text, "utf8");
  return createHash("sha1").update(Buffer.concat([Buffer.from(`blob ${body.length}\0`), body])).digest("hex");
};

const files = ["AGENTS.md", ...walk(join(root, "docs")).map((f) => relative(root, f))].sort();
const docs = files.map((path) => {
  const content = readFileSync(join(root, path), "utf8");
  return { path, sha: blobSha(content), content };
});

let commit = process.env.CF_PAGES_COMMIT_SHA || process.env.GITHUB_SHA || "";
if (!commit) {
  try {
    commit = execSync("git rev-parse HEAD", { cwd: root, stdio: ["ignore", "pipe", "ignore"] }).toString().trim();
  } catch {
    commit = "unknown";
  }
}

const out = `// GENERATED by scripts/build-knowledge.mjs. Do not edit; not committed.
export const KNOWLEDGE_BUILD = ${JSON.stringify({ commit, builtAt: new Date().toISOString() })};
export const KNOWLEDGE_DOCS: { path: string; sha: string; content: string }[] = ${JSON.stringify(docs)};
`;
writeFileSync(join(root, "src/content/knowledge.generated.ts"), out);
console.log(`knowledge: bundled ${docs.length} documents at ${commit.slice(0, 7)}`);
